#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int maxSelectedElements(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        std::unordered_map<int, int> dp;
        int ans = 0;
        for (int x : nums) {
            dp[x + 1] = dp[x] + 1;
            dp[x] = dp[x - 1] + 1;
            ans = std::max({ans, dp[x + 1], dp[x]});
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxSelectedElements(int[] nums) {
        Arrays.sort(nums);
        Map<Integer, Integer> dp = new HashMap<>();
        int ans = 0;
        for (int x : nums) {
            int dpX = dp.getOrDefault(x, 0);
            int dpXMinus1 = dp.getOrDefault(x - 1, 0);
            dp.put(x + 1, dpX + 1);
            dp.put(x, dpXMinus1 + 1);
            ans = Math.max(ans, Math.max(dpX + 1, dpXMinus1 + 1));
        }
        return ans;
    }
}

var maxSelectedElements = function(nums) {
    nums.sort((a, b) => a - b);
    const dp = new Map();
    let ans = 0;
    for (const x of nums) {
        const dpX = dp.get(x) || 0;
        const dpXMinus1 = dp.get(x - 1) || 0;
        dp.set(x + 1, dpX + 1);
        dp.set(x, dpXMinus1 + 1);
        ans = Math.max(ans, dpX + 1, dpXMinus1 + 1);
    }
    return ans;
};
